
#[test]
fn genuine_work_binding_matches_later_effects_but_rejects_new_scopes_and_issuers(){
 let issuer=OriginalSourceTurnIssuer::new();let turn=issuer.issue().unwrap();let mut authority=OriginalWorkAuthority::new(Source{issuer,turn:turn.identity(),counter:Arc::new(AtomicUsize::new(0)),checks:Arc::new(AtomicUsize::new(0))});let mut context=&turn;let mut binding=None;
 authority.with_loan(&mut context,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let mut original=OriginalWorkBorrow::new(&mut work);let key=original.binding_identity().unwrap();binding=Some(key);
  for _ in 0..2{let(mut action,mut receipt,mut claim,mut marker)=(None,None,None,None);assert_eq!(original.prepare(1,&mut action).unwrap(),Some(true));{let mut scope=original.performed_scope(action,&mut receipt,&mut claim).unwrap();let effect=scope.effect(grant(),1,&mut marker).unwrap();assert!(key.matches_effect(&effect));}assert_eq!(claim.take().unwrap().unwrap(),0);original.cancel(&mut action).unwrap();}assert_eq!(original.actual(),0);
 }).unwrap();
 authority.with_loan(&mut context,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let mut original=OriginalWorkBorrow::new(&mut work);let(mut action,mut receipt,mut claim,mut marker)=(None,None,None,None);assert_eq!(original.prepare(1,&mut action).unwrap(),Some(true));{let mut scope=original.performed_scope(action,&mut receipt,&mut claim).unwrap();let effect=scope.effect(grant(),1,&mut marker).unwrap();assert!(!binding.unwrap().matches_effect(&effect));}assert_eq!(claim.take().unwrap().unwrap(),0);original.cancel(&mut action).unwrap();
 }).unwrap();
 let source=authority.into_recipient().ok().unwrap();let mut foreign=OriginalWorkAuthority::new(source);foreign.with_loan(&mut context,|loan|{let mut loan=loan.reborrow();let mut work=OriginalWork::empty();work.recipient=Some(&mut loan);let mut original=OriginalWorkBorrow::new(&mut work);let(mut action,mut receipt,mut claim,mut marker)=(None,None,None,None);assert_eq!(original.prepare(1,&mut action).unwrap(),Some(true));{let mut scope=original.performed_scope(action,&mut receipt,&mut claim).unwrap();let effect=scope.effect(grant(),1,&mut marker).unwrap();assert!(!binding.unwrap().matches_effect(&effect));}assert_eq!(claim.take().unwrap().unwrap(),0);original.cancel(&mut action).unwrap();}).unwrap();assert!(foreign.into_recipient().is_ok());
}
